      music = "09_Suspect",
      renming = "??",
      renwu = "npc",
      sentence = "Is everything pretty much prepared for the sacrifice ceremony? There's a \"special\" offering this year. The River King is sure to be pleased.",
      next = {3}
    },
    [3] = {
      beijing = 1811,
      dialog = 2,
      idx = 5,
      music = "09_Suspect",
      renming = "??",
      renwu = "npc",
      sentence = "Of course. Our village is dependent on the River King's protection. We must show the utmost respect to our grand ancestor.",
      next = {4}
    },
    [4] = {
      beijing = 1811,
      dhead = 109,
      dialog = 1,
      music = "09_Suspect",
      renming = "$u",
      renwu = "npc",
      sentence = "...Wow, these superstitions are straight out of the Dark Ages...",
      next = {5}
    },
    [5] = {
      beijing = 1811,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      sentence = "I crouched up in a grubby corner, unable to get free of the thick rope around my wrists. All I could do was warily size up the room around me.",
      next = {6}
    },
    [6] = {
      beijing = 1811,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      sentence = "The spacious room lacked even a hint of human warmth. Sunlight didn't seem to ever reach down here, and the carved beams and painted rafter in the shadows seemed to exude a gloomy aura.",
      next = {7}
    },
    [7] = {
      beijing = 1811,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      sentence = "A stone statue stood on a table in the distance. There was a densely-carved swarm of poisonous insects—venomites—at its feet, and all around it was a thick layer of dust.",
      next = {8}
    },
    [8] = {
      beijing = 1811,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      sentence = "I recalled the materials I'd read before coming to this historical town, how the legends said the River King stepped on venomites and was immune to all poison.",
      next = {9}
    },
    [9] = {
      beijing = 1811,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      sentence = "Apparently, this was the stature of the \"River King\" the villagers had just mentioned, and this was my destination for this trip—the Old River King Mansion.",
      next = {10}
    },
    [10] = {
      beijing = 1811,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      sentence = "As a producer of horror games, I was excited to make a pilgrimage to the ancient River King Village to gather material. Little did I expect that upon entering the village I'd be knocked unconscious and thrown in here.",
      next = {11}
    },
    [11] = {
      beijing = 1811,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      sentence = "Thankfully before coming here, I took the proper precautions. Now that I've been out of contact with my family for twelve hours, they ought to have contacted the police by now.",
      next = {12}
    },
    [12] = {
      beijing = 1811,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      sentence = "For the past few years, I've been to lots of bizarre places to gather material, so I've accumulated quite a bit of experience.",
      next = {13}
    },
    [13] = {
      beijing = 1811,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      sentence = "But this was definitely the first time I'd ever been outright kidnapped. As I suppressed the fear in my heart, I calmly looked around for any and all opportunities to escape.",
      next = {14}
    },
    [14] = {
      beijing = 1811,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      sentence = "I darted a glance at the figures in the distance outside the door. The guards seemed unwilling to come too close out of some kind of dread of the place.",
      next = {15}
    },
    [15] = {
      beijing = 1811,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      sentence = "I carefully straightened myself up and scooted my tied-up feet.",
      next = {16}
    },
    [16] = {
      beijing = 1811,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      sentence = "But the ceremonial clothes I was wearing were both long and heavy, and I had several strings of silver bells hung from me that rang out when I so much as moved.",
      next = {17}
    },
    [17] = {
      beijing = 1811,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      sentence = "After taking a few steps, I lost control and spilled to the ground, knocking down the statue of the River King on the table in the process.",
