    },
    [18] = {
      beijing = 1811,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      sentence = "When the stone statue split open, it gave off a faint, momentary green glow, and I felt a chill wind blow on my back.",
      next = {19}
    },
    [19] = {
      beijing = 1811,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      sentence = "I felt a strange prickle of fear inside, and I scurried carefully back to the corner.",
